// Pure pricing helpers for the metered-software pages (/developers, /pricing, the API portal).
//
// Nothing in this file sets a number. Every figure it returns is derived from one of two registries:
//   * lib/products.ts      PAYG (unit price, caps, free allowance, minimum invoice) and the API plans
//   * public/reference/tools.json   units per endpoint, generated by the engine itself and diffed in CI
// so the rate card, the estimator and the break-even sentence cannot disagree with what the engine meters
// or what checkout charges. No file but lib/products.ts may carry a euro figure; amounts are formatted here,
// never typed.
//
// No React, no fetch, no Node APIs: the same module runs in a server page, a client component and a test.

import { API_PRODUCTS, PAYG, eurFromCents, paygCapUnits, type Product } from "@/lib/products";

/** One row of public/reference/tools.json `tools[]`, the fields the pricing surfaces read. */
export interface ToolRate {
  name: string;
  endpoint: string;
  units: number;
  tier: string;
  returns?: string;
  description?: string;
}

/**
 * Endpoints the engine bills per hall in the request rather than once per call. Mirrors
 * gridforge/api/metering.py units_for(); the tool catalogue says the same thing in words
 * ("Bills one unit per hall") and tests/site/payg-pricing.test.ts compares the two so this cannot drift quietly.
 */
export const PER_HALL_ENDPOINTS: readonly string[] = ["/v1/portfolio"];

export function isPerHall(rate: Pick<ToolRate, "endpoint">): boolean {
  return PER_HALL_ENDPOINTS.includes(rate.endpoint);
}

/**
 * Read `tools[]` out of public/reference/tools.json (already parsed). Anything that is not a well-formed row is
 * dropped rather than repaired: a rate card with a missing row is honest, one with a guessed row is not.
 */
export function parseToolRates(json: unknown): ToolRate[] {
  const tools = (json as { tools?: unknown } | null)?.tools;
  if (!Array.isArray(tools)) return [];
  const out: ToolRate[] = [];
  for (const t of tools) {
    if (t === null || typeof t !== "object") continue;
    const r = t as Record<string, unknown>;
    if (typeof r.name !== "string" || typeof r.endpoint !== "string") continue;
    if (typeof r.units !== "number" || !Number.isFinite(r.units) || r.units < 0) continue;
    out.push({
      name: r.name,
      endpoint: r.endpoint,
      units: Math.trunc(r.units),
      tier: typeof r.tier === "string" ? r.tier : "client",
      returns: typeof r.returns === "string" ? r.returns : undefined,
      description: typeof r.description === "string" ? r.description : undefined,
    });
  }
  return out;
}

/** "A constraint screen is 1 unit, a full study is 5, a portfolio run is 1 per hall." Built from the rows; omits what it cannot find. */
export function unitSummary(rates: readonly ToolRate[]): string {
  const by = (ep: string) => rates.find((r) => r.endpoint === ep);
  const u = (n: number) => `${n} unit${n === 1 ? "" : "s"}`;
  const parts: string[] = [];
  const screen = by("/v1/screen");
  const study = by("/v1/study");
  const portfolio = by("/v1/portfolio");
  if (screen) parts.push(`a constraint screen is ${u(screen.units)}`);
  if (study) parts.push(`a full study is ${u(study.units)}`);
  if (portfolio) parts.push(`a portfolio run is ${u(portfolio.units)} per hall`);
  if (parts.length === 0) return "";
  const text = parts.join(", ");
  return text.charAt(0).toUpperCase() + text.slice(1) + ".";
}

/** Free tools are the ones the catalogue prices at zero units; the public tier is the same set. */
export function isFree(rate: Pick<ToolRate, "units">): boolean {
  return rate.units === 0;
}

/** Whole halls only, at least one. A portfolio of zero halls is billed as one by the engine, so it is here. */
export function normaliseHalls(raw: unknown): number {
  const n = typeof raw === "number" ? raw : Number(raw);
  if (!Number.isFinite(n)) return 1;
  return Math.max(1, Math.min(10_000, Math.trunc(n)));
}

/** Units one call to this endpoint costs. Mirrors units_for() on the engine. */
export function unitsFor(rate: Pick<ToolRate, "endpoint" | "units">, halls = 1): number {
  const base = Math.max(0, Math.trunc(rate.units));
  return isPerHall(rate) ? base * normaliseHalls(halls) : base;
}

/** Euro cents to a price a person reads: whole euros stay whole, anything else shows two decimals. */
export function eurExact(cents: number): string {
  const c = Math.round(cents);
  const whole = c % 100 === 0;
  return new Intl.NumberFormat("en-IE", {
    style: "currency",
    currency: "EUR",
    minimumFractionDigits: whole ? 0 : 2,
    maximumFractionDigits: whole ? 0 : 2,
  }).format(c / 100);
}

/** A timestamp as a person reads it, always in UTC so the page says the same thing in every timezone. */
export function formatUtc(ts: string): string {
  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return ts;
  return `${d.toISOString().slice(0, 16).replace("T", " ")} UTC`;
}

export interface OperationEstimate {
  endpoint: string;
  halls: number;
  units: number;
  /** What this one call costs on pay-as-you-go, in cents (0 for a free endpoint). */
  cents: number;
  free: boolean;
  /** The rule the units came from, in words, so the number is never unexplained. */
  basis: string;
}

export function estimateOperation(rate: ToolRate, halls = 1): OperationEstimate {
  const h = isPerHall(rate) ? normaliseHalls(halls) : 1;
  const units = unitsFor(rate, h);
  const free = isFree(rate);
  const basis = free
    ? "Free: this endpoint bills zero units and never touches an allowance."
    : isPerHall(rate)
      ? `${rate.units} unit${rate.units === 1 ? "" : "s"} per hall in the request, ${h} hall${h === 1 ? "" : "s"}.`
      : `${rate.units} unit${rate.units === 1 ? "" : "s"} per call.`;
  return { endpoint: rate.endpoint, halls: h, units, cents: units * PAYG.unitPriceCents, free, basis };
}

/** How many calls of this size one free allowance covers. Zero for a call larger than the allowance. */
export function callsInFreeAllowance(units: number): number | null {
  if (units <= 0) return null; // free: unlimited, so "how many fit" has no answer
  return Math.floor(PAYG.freeAllowanceUnits / units);
}

/** Units a customer-set cap allows, validated against the registry's bounds. */
export function capUnitsFor(capEur: number): number {
  return paygCapUnits(capEur);
}

export interface CapCheck {
  ok: boolean;
  capEur: number | null;
  units: number | null;
  error: string | null;
}

/**
 * The cap chooser's validation. The input is text because that is what a form gives us; anything that is
 * not a whole number of euros inside the registry's bounds is refused with the bounds in the message.
 */
export function validateCapEur(raw: unknown): CapCheck {
  const text = typeof raw === "string" ? raw.trim() : raw;
  if (text === "" || text === null || text === undefined) {
    return { ok: false, capEur: null, units: null, error: "Enter a monthly cap in whole euros." };
  }
  const n = typeof text === "number" ? text : Number(text);
  if (!Number.isFinite(n) || !Number.isInteger(n)) {
    return { ok: false, capEur: null, units: null, error: "The cap must be a whole number of euros." };
  }
  if (n < PAYG.minCapEur || n > PAYG.maxCapEur) {
    return {
      ok: false,
      capEur: null,
      units: null,
      error: `The cap must be between ${eurExact(PAYG.minCapEur * 100)} and ${eurExact(PAYG.maxCapEur * 100)} a month.`,
    };
  }
  return { ok: true, capEur: n, units: paygCapUnits(n), error: null };
}

/**
 * Suggested caps. Built from the registry's own bounds and default so they cannot fall outside them:
 * the minimum, the default, and the maximum, de-duplicated and in order.
 */
export function capPresets(): number[] {
  return Array.from(new Set([PAYG.minCapEur, PAYG.defaultCapEur, PAYG.maxCapEur])).sort((a, b) => a - b);
}

// --- plans vs pay-as-you-go ---------------------------------------------------------------------------

export interface BreakEven {
  plan: Product;
  planCents: number;
  includedUnits: number;
  /** Smallest monthly volume at which the plan's price is no more than paying per unit. */
  breakEvenUnits: number;
  /** What the plan's full allowance would cost on pay-as-you-go. */
  paygCentsForIncluded: number;
  /** Does the plan ever cost less than PAYG inside its own allowance? Computed, not assumed. */
  everCheaper: boolean;
  /** Is the break-even above what a customer-set cap can reach? Then PAYG cannot out-spend the plan. */
  beyondCap: boolean;
  text: string;
}

/**
 * Where a plan starts to cost less than metering, from the registry: ceil(plan price / unit price).
 * Plans have no overage (the engine answers 402 at the quota), so the comparison only holds up to the
 * plan's included units, and the sentence says so.
 */
export function breakEven(plan: Product, unitPriceCents: number = PAYG.unitPriceCents): BreakEven {
  const includedUnits = plan.apiUnits ?? 0;
  const breakEvenUnits = Math.ceil(plan.amountCents / unitPriceCents);
  const paygCentsForIncluded = includedUnits * unitPriceCents;
  const everCheaper = includedUnits > 0 && breakEvenUnits <= includedUnits;
  const maxCapUnits = paygCapUnits(PAYG.maxCapEur);
  const beyondCap = breakEvenUnits > maxCapUnits;
  const price = `${eurFromCents(plan.amountCents)} a month`;
  const fmt = (n: number) => n.toLocaleString("en-IE");
  let text: string;
  if (!everCheaper) {
    text =
      `${plan.name} (${price}) does not undercut pay-as-you-go inside its own ${fmt(includedUnits)} units: ` +
      `those units would cost ${eurExact(paygCentsForIncluded)} metered.`;
  } else {
    text =
      `${plan.name} (${price}, ${fmt(includedUnits)} units included) costs less than pay-as-you-go from ` +
      `${fmt(breakEvenUnits)} units a month; below that, metering costs less.`;
    if (beyondCap) {
      text +=
        ` That is above the ${fmt(maxCapUnits)} units the highest pay-as-you-go cap allows ` +
        `(${eurExact(PAYG.maxCapEur * 100)}), so a cap-limited account cannot reach it.`;
    }
  }
  return { plan, planCents: plan.amountCents, includedUnits, breakEvenUnits, paygCentsForIncluded, everCheaper, beyondCap, text };
}

export function breakEvens(plans: readonly Product[] = API_PRODUCTS): BreakEven[] {
  return plans.map((p) => breakEven(p)).sort((a, b) => a.planCents - b.planCents);
}

export interface MonthlyComparison {
  units: number;
  paygCents: number;
  /** The cheapest option for this volume among pay-as-you-go and the plans whose allowance covers it. */
  cheapest: { kind: "payg" | "plan" | "free"; label: string; cents: number };
  /** Plans whose included units cover the volume, with their monthly price. */
  plansCovering: { plan: Product; cents: number }[];
  /** True when the volume is above the highest cap and above every plan allowance: engagement territory. */
  beyondEverything: boolean;
  /** The month's pay-as-you-go charge is below the minimum invoice and would be carried forward, not invoiced. */
  carried: boolean;
  /** A month inside the free allowance costs nothing and needs no card. */
  withinFree: boolean;
  /** The cap the volume needs, in whole euros, or null when it exceeds the highest cap. */
  capNeededEur: number | null;
}

/** What a month of `units` costs, with the honest alternatives, all from the registry. */
export function compareMonthly(units: number, plans: readonly Product[] = API_PRODUCTS): MonthlyComparison {
  const u = Math.max(0, Math.trunc(Number.isFinite(units) ? units : 0));
  const paygCents = u * PAYG.unitPriceCents;
  const withinFree = u <= PAYG.freeAllowanceUnits;
  const covering = plans
    .filter((p) => (p.apiUnits ?? 0) >= u)
    .map((p) => ({ plan: p, cents: p.amountCents }))
    .sort((a, b) => a.cents - b.cents);
  const maxCapUnits = paygCapUnits(PAYG.maxCapEur);
  const paygPossible = u <= maxCapUnits;
  let cheapest: MonthlyComparison["cheapest"];
  if (withinFree) {
    cheapest = { kind: "free", label: "Free allowance", cents: 0 };
  } else if (paygPossible && (covering.length === 0 || paygCents <= covering[0].cents)) {
    cheapest = { kind: "payg", label: "Pay as you go", cents: paygCents };
  } else if (covering.length > 0) {
    cheapest = { kind: "plan", label: covering[0].plan.name, cents: covering[0].cents };
  } else {
    cheapest = { kind: "payg", label: "Pay as you go", cents: paygCents };
  }
  const capNeededEur = paygPossible ? Math.max(PAYG.minCapEur, Math.ceil(paygCents / 100)) : null;
  return {
    units: u,
    paygCents,
    cheapest,
    plansCovering: covering,
    beyondEverything: !paygPossible && covering.length === 0,
    carried: !withinFree && paygCents > 0 && paygCents < PAYG.minInvoiceCents,
    withinFree,
    capNeededEur,
  };
}

// --- the rule, in one sentence, from the registry -----------------------------------------------------

/** The billing rule as shown to a customer. One function so every page says it identically. */
export function billingRuleText(): string {
  return (
    `A month's charge is the net ledger units for the UTC month (charges minus refunds) at ` +
    `${eurExact(PAYG.unitPriceCents)} a unit, invoiced monthly in arrears. A month whose charge is under the ` +
    `${eurExact(PAYG.minInvoiceCents)} minimum invoice is not invoiced on its own: it is carried forward and added to the next month, ` +
    `and so on from month to month. A balance that never reaches ${eurExact(PAYG.minInvoiceCents)} is never invoiced. ` +
    `A request that is rejected, unauthorised, invalid or fails is refunded and never charged, and a retry ` +
    `with the same Idempotency-Key is never charged twice. Free-allowance usage is never invoiced. The customer's own ` +
    `monthly cap is a hard stop: beyond it the engine answers 402 and nothing more accrues.`
  );
}

/** The explicit statement shown next to the enable button. Registry-driven, never typed with a number. */
export function enableStatement(capEur: number | null): string {
  const cap = capEur === null ? "your cap" : eurExact(capEur * 100);
  return `No charge is made now. Usage is invoiced monthly in arrears. There is a hard stop at ${cap}: the engine refuses further paid calls with a 402 rather than going over it.`;
}

/**
 * Hours before the free-allowance link is re-sent to the same address. Mirrors FREE_RESEND_COOLDOWN_MS in
 * lib/payg-accounts.ts (server-only, so not imported here); tests/site/payg-pricing.test.ts compares the two.
 */
export const FREE_RESEND_HOURS = 6;

export const FREE_ALLOWANCE_TEXT =
  `${PAYG.freeAllowanceUnits} units a month, no card. Free-allowance usage is never invoiced; ` +
  `when it runs out the engine answers 402 and nothing is charged.`;
